import urllib.request,urllib.error; r=urllib.request.Request('http://consumidor:8000/',method='GET'); 
try:
 with urllib.request.urlopen(r,timeout=2) as x: print('STATUS='+str(x.status)); print('BODY='+x.read().decode())
except urllib.error.HTTPError as e: print('STATUS='+str(e.code)); print('BODY='+e.read().decode())
except (urllib.error.URLError,TimeoutError,OSError) as e: print('STATUS=0'); print('BODY='+str(e))

